    w = len(grid[0])

    out = [row[:] for row in grid]

    eights = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    twos = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]

    if not eights:
        return out

    eights_set = set(eights)

    def sign(x):
        return (x > 0) - (x < 0)

    # Determine the diagonal direction of the 8-line
    if len(eights) >= 2:
        base = eights[0]
        dr = dc = None
        for r, c in eights[1:]:
            ddr = sign(r - base[0])
            ddc = sign(c - base[1])
            if ddr != 0 and ddc != 0:
                dr, dc = ddr, ddc
                break
        if dr is None:
            return out
    else:
        # Fallback for degenerate cases
        dr, dc = 1, 1

    # Find endpoints of the 8 diagonal chain
    endpoints = []
    for r, c in eights:
        cnt = 0
        for rr, cc in ((r - dr, c - dc), (r + dr, c + dc)):
            if (rr, cc) in eights_set:
                cnt += 1
        if cnt <= 1:
            endpoints.append((r, c))

    if len(endpoints) < 2:
        # Fallback: use extreme points along the line
        proj = sorted(eights, key=lambda p: (p[0] * dr + p[1] * dc, p[0], p[1]))
        endpoints = [proj[0], proj[-1]]

    def outward_direction(endpoint):
        r, c = endpoint
        neighbors = []
        for rr, cc in ((r - dr, c - dc), (r + dr, c + dc)):
            if (rr, cc) in eights_set:
                neighbors.append((rr, cc))
        if neighbors:
            nr, nc = neighbors[0]
            return sign(r - nr), sign(c - nc)
        return dr, dc

    candidates = []
    for ep in endpoints[:2]:
        candidates.append((ep, outward_direction(ep)))

    def simulate(start, d):
        r, c = start
        drx, dcx = d
        path = []
        while True:
            nr, nc = r + drx, c + dcx
            if not (0 <= nr < h and 0 <= nc < w):
                return {"hit": "boundary", "last": (r, c), "path": path}
            val = grid[nr][nc]
            if val == 0:
                path.append((nr, nc))
                r, c = nr, nc
            elif val == 2:
                return {"hit": "2", "last": (r, c), "path": path}
            else:
                return {"hit": "other", "last": (r, c), "path": path}

    chosen = None
    chosen_sim = None
    for ep, d in candidates:
        sim = simulate(ep, d)
        if sim["hit"] == "2":
            chosen = (ep, d)
            chosen_sim = sim
            break

    if chosen is None:
        # Fallback: choose the longer zero-path candidate
        best_len = -1
        for ep, d in candidates:
            sim = simulate(ep, d)
            if len(sim["path"]) > best_len:
                best_len = len(sim["path"])
                chosen = (ep, d)
                chosen_sim = sim

    start, (drx, dcx) = chosen

    for r, c in chosen_sim["path"]:
        if out[r][c] == 0:
            out[r][c] = 3

    if chosen_sim["hit"] == "2":
        rows2 = {r for r, c in twos}
        cols2 = {c for r, c in twos}

        if len(rows2) == h:
            # vertical wall
            rdr, rdc = drx, -dcx
        elif len(cols2) == w:
            # horizontal wall
            rdr, rdc = -drx, dcx
        else:
            # Fallback heuristic
            if len(rows2) > len(cols2):
                rdr, rdc = drx, -dcx
            else:
                rdr, rdc = -drx, dcx

        r, c = chosen_sim["last"]
        while True:
            nr, nc = r + rdr, c + rdc
            if not (0 <= nr < h and 0 <= nc < w):
                break
            if out[nr][nc] != 0:
                break
            out[nr][nc] = 3
            r, c = nr, nc

    return out

